/** @var array{total: int, queue_sent: int, bed_sent: int, queue_percentage: float|null, bed_percentage: float|null, latest: array<string, mixed>|null} $summary */
$months = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];
$percent = static fn (?float $value): string => $value === null ? '—' : rtrim(rtrim(number_format($value, 1, ',', '.'), '0'), ',') . '%';
$latest = $summary['latest'];
$latestStamp = $latest ? strtotime($latest['at']) : null;
$latestDate = $latestStamp ? date('d', $latestStamp) . ' ' . $months[(int) date('n', $latestStamp) - 1] . date(' Y • H:i', $latestStamp) . ' WIB' : 'Belum ada audit';
?>
